{"id":"0b92b112-f315-4479-9331-7a815deec27e","revision":1,"name":"Ornament Region Styles","description":"Paints organic regions with watercolor, ink and six local motif families. Pattern helpers are scene-prototype internals pending separate reusable extraction.","updatedAt":"2026-09-16T10:30:51.965Z","source":{"sdkVersion":"0.4.0","entry":"ornament-renderer.ts","files":{"ornament-line-patterns.ts":"// The Ornament renderer supplies LoRegion plus loHash and loNoise. Both
// helpers return coverage, letting the renderer keep a single paint pass.
export const ornamentLinePatternHelpers = `fn loLineCoverage(distance: f32, halfWidth: f32, aa: f32) -> f32 {
  return 1.0 - smoothstep(halfWidth - aa, halfWidth + aa, abs(distance));
}

fn loMembranes(r: LoRegion, p: vec2f, t: f32, settings: vec4f) -> f32 {
  let density = settings.x;
  let width = settings.y;
  let variation = settings.z;
  let motion = settings.w;
  let along = dot(r.local, r.tangent);
  let across = dot(r.local, vec2f(-r.tangent.y, r.tangent.x));
  let identity = vec2f(r.identity, r.parent);
  let hubCount = 1 + i32(floor(loHash(identity + 12.7) * 2.0));
  let aa = max(fwidth(along) + fwidth(across), 0.0010);
  var membrane = 0.0;
  for (var hubIndex = 0; hubIndex < 3; hubIndex++) {
    if (hubIndex >= hubCount) { break; }
    let hubSeed = identity + vec2f(f32(hubIndex) * 19.1, 71.3);
    let hub = vec2f(
      mix(-0.10, 0.10, loHash(hubSeed)),
      mix(-0.08, 0.08, loHash(hubSeed + 7.9)),
    );
    let q = vec2f(along, across) - hub;
    let angle = atan2(q.y, q.x);
    let radius = length(q);
    let petalCount = 7.0 + floor(loHash(hubSeed + 31.0) * 4.0);
    let bowedAngle = angle + sin(radius * 4.6 + hubSeed.x + t * motion * 0.05)
      * variation * 0.78;
    let phase = bowedAngle * petalCount / 6.283185 + loHash(hubSeed + 43.0);
    // The angular distance is converted to a world-space distance by radius,
    // so each fan line stays clean and reaches its owning cell boundary.
    let angularDistance = (fract(phase + 0.5) - 0.5) * 6.283185 / petalCount;
    let spokeDistance = radius * sin(angularDistance);
    let spokeWidth = max(0.0045 * width, aa * (1.25 + width * 0.85));
    let spoke = loLineCoverage(spokeDistance, spokeWidth, aa);
    membrane = max(membrane, spoke);
  }
  let gate = smoothstep(0.08, 0.46, density);
  return membrane * gate;
}

fn loContours(r: LoRegion, p: vec2f, t: f32, settings: vec4f) -> f32 {
  let density = settings.x;
  let width = settings.y;
  let variation = settings.z;
  let motion = settings.w;
  let along = dot(r.local, r.tangent);
  let across = dot(r.local, vec2f(-r.tangent.y, r.tangent.x));
  let identity = vec2f(r.identity, r.parent);
  let offset = vec2f(
    (loHash(identity + 103.0) - 0.5) * 0.42,
    (loHash(identity + 211.0) - 0.5) * 0.34,
  );
  let q = vec2f(along, across) - offset;
  let angle = atan2(q.y, q.x);
  let stretch = vec2f(0.82 + loHash(identity + 17.0) * 0.52,
    0.70 + loHash(identity + 29.0) * 0.42);
  let radius = length(q / stretch);
  let lobes = 2.0 + floor(loHash(identity + 37.0) * 3.0);
  let waviness = sin(angle * lobes + identity.x * 0.17) * (0.040 + variation * 0.085)
    + sin(angle * (lobes + 2.0) - t * motion * 0.07) * 0.018;
  let contourRadius = radius + waviness;
  let spacing = mix(0.29, 0.105, clamp(density * 0.55, 0.0, 1.0));
  let phase = contourRadius / spacing + loHash(identity + 61.0) * 0.42;
  let contour = abs(fract(phase + 0.5) - 0.5) * spacing;
  let aa = max(fwidth(contourRadius), 0.0010);
  let lineWidth = max(0.0052 * width, aa * (1.10 + width * 0.78));
  let line = loLineCoverage(contour, lineWidth, aa);
  let taper = smoothstep(0.04, 0.24, r.edge) * (1.0 - smoothstep(1.15, 1.75, contourRadius));
  return line * taper;
}
`;
","ornament-packed-patterns.ts":"// Packed ornament patterns for lux/ornament-regions/v1. LoRegion.local and
// LoRegion.tangent are both expressed in the region's attached local frame.
export const ornamentPackedPatterns = `fn loPatternFrame(r: LoRegion) -> mat2x2f {
  let tangent = normalize(r.tangent);
  return mat2x2f(tangent, vec2f(-tangent.y, tangent.x));
}

fn loSpirals(r: LoRegion, p: vec2f, t: f32, settings: vec4f) -> f32 {
  let density = max(settings.x, 0.05);
  let width = max(settings.y, 0.05);
  let variation = clamp(settings.z, 0.0, 1.5);
  let motion = max(settings.w, 0.0);
  let frequency = 7.0 * density;
  let attached = transpose(loPatternFrame(r)) * r.local;
  let grid = attached * frequency;
  let home = floor(grid);
  let pixel = max(max(fwidth(p.x), fwidth(p.y)) * frequency, 0.0008);
  var coverage = 0.0;

  for (var y = -1; y <= 1; y++) {
    for (var x = -1; x <= 1; x++) {
      let cell = home + vec2f(f32(x), f32(y));
      let seed = cell + vec2f(r.identity * 0.071, r.identity * 0.113);
      let hx = loHash(seed + 17.3);
      let hy = loHash(seed + 43.7);
      let hr = loHash(seed + 91.1);
      let phase = loHash(seed + 131.9) * 6.2831853;
      let jitter = (vec2f(hx, hy) - 0.5) * (0.14 + variation * 0.20);
      let drift = vec2f(cos(t * 0.083 * motion + phase), sin(t * 0.067 * motion + phase));
      let center = cell + vec2f(0.5) + jitter + drift * motion * 0.018;
      let q = grid - center;
      let radius = mix(0.22, 0.47, hr) * mix(0.92, 1.08, clamp(variation, 0.0, 1.0));
      let radial = length(q);
      let angle = atan2(q.y, q.x) + t * motion * (0.045 + hr * 0.035);
      let turns = 2.15 + variation * mix(0.65, 1.55, hx);
      let pitch = radius / max(turns, 0.5);
      let winding = abs(fract(radial / pitch - angle / 6.2831853 + 0.5) - 0.5) * pitch;
      let inkWidth = radius * (0.038 + hr * 0.014) * width;
      let line = 1.0 - smoothstep(inkWidth, inkWidth + pixel, winding);
      let packed = 1.0 - smoothstep(radius - pixel, radius + pixel, radial);
      coverage = max(coverage, line * packed);
    }
  }
  return clamp(coverage, 0.0, 1.0);
}

fn loRings(r: LoRegion, p: vec2f, t: f32, settings: vec4f) -> f32 {
  let density = max(settings.x, 0.05);
  let width = max(settings.y, 0.05);
  let variation = clamp(settings.z, 0.0, 1.5);
  let motion = max(settings.w, 0.0);
  let frequency = 6.2 * density;
  let attached = transpose(loPatternFrame(r)) * r.local;
  let grid = attached * frequency;
  let home = floor(grid);
  let pixel = max(max(fwidth(p.x), fwidth(p.y)) * frequency, 0.0008);
  var coverage = 0.0;

  for (var y = -1; y <= 1; y++) {
    for (var x = -1; x <= 1; x++) {
      let cell = home + vec2f(f32(x), f32(y));
      let seed = cell + vec2f(r.identity * 0.097, r.identity * 0.149);
      let hx = loHash(seed + 11.7);
      let hy = loHash(seed + 37.1);
      let hr = loHash(seed + 79.9);
      let hd = loHash(seed + 151.3);
      let phase = loHash(seed + 211.7) * 6.2831853;
      let jitter = (vec2f(hx, hy) - 0.5) * (0.14 + variation * 0.19);
      let drift = vec2f(sin(t * 0.061 * motion + phase), cos(t * 0.073 * motion + phase));
      let center = cell + vec2f(0.5) + jitter + drift * motion * 0.016;
      let q = grid - center;
      let baseRadius = mix(0.17, 0.48, hr);
      let pulse = 1.0 + motion * 0.025 * sin(t * 0.052 + phase);
      let radius = baseRadius * mix(0.92, 1.10, variation * hr) * pulse;
      let radial = length(q);
      let inkWidth = (0.023 + hx * 0.012) * width;
      let ringDistance = abs(radial - radius);
      let ring = 1.0 - smoothstep(inkWidth, inkWidth + pixel, ringDistance);
      let dotRadius = radius * mix(0.18, 0.31, hy);
      let dot = (1.0 - smoothstep(dotRadius - pixel, dotRadius + pixel, radial))
        * step(0.82 - variation * 0.035, hd);
      coverage = max(coverage, max(ring, dot));
    }
  }
  return clamp(coverage, 0.0, 1.0);
}
`;
","ornament-renderer.ts":"import { defineComponent, type ShaderFieldResource } from '@lux/visual-sdk';
import {
  Scene,
  Mesh,
  PlaneGeometry,
  MeshBasicNodeMaterial,
  OrthographicCamera,
  Vector4,
} from 'three/webgpu';
import { uniform, uv, wgslFn } from 'three/tsl';
import { ornamentPackedPatterns } from './ornament-packed-patterns.ts';
import { ornamentLinePatternHelpers } from './ornament-line-patterns.ts';
import { ornamentRibbonPatternHelpers } from './ornament-ribbon-patterns.ts';

// wgslFn selects the first function as its entry. Keep the paint pass before
// the supplied helpers, including the LoRegion declaration and noise basis.
const paintPass = `
fn livingOrnament(st: vec2f, view: vec4f, shape: vec4f, detail: vec4f,
  pigment: vec4f, material: vec4f, ink: vec4f, pattern: vec4f, patternStyle: vec4f) -> vec4f {
  let p = (st - 0.5) * vec2f(view.y, 1.0) * 2.0;
  let region = loRegion(p, view.x, view.z, shape, detail);
  var wash = loWash(region, p, view.x, pigment, material);
  let id = i32(region.identity + 0.5);
  if (id == 110) { wash = mix(wash, vec3f(0.56, 0.78, 0.84), 0.78); }
  var marks = 0.0;
  switch id {
    case 101, 105, 109, 113: { marks = loSpirals(region, p, view.x, pattern); }
    case 103, 112, 114: { marks = loRings(region, p, view.x, pattern); }
    case 102, 104, 107, 108: { marks = loMembranes(region, p, view.x, pattern); }
    case 115: { marks = loContours(region, p, view.x, pattern); }
    case 110, 111: { marks = loRibbonMarks(region, p, view.x, pattern); }
    default: { marks = loHatchMarks(region, p, view.x, pattern); }
  }
  var rest = select(1.0, 1.0 - patternStyle.y, id == 115);
  if (id == 101) {
    let clusteredGround = 1.0 - smoothstep(-0.45, 0.2, p.x + p.y * 0.35);
    rest = mix(1.0, clusteredGround, min(patternStyle.y * 1.2, 1.0));
  }
  let inset = smoothstep(ink.x * 1.7, ink.x * 3.2, region.edge);
  let light = dot(wash, vec3f(0.2126, 0.7152, 0.0722));
  var motifInk = select(vec3f(0.006, 0.004, 0.009), vec3f(0.86, 0.75, 0.60), light < 0.16);
  if (id == 110 || id == 111) { motifInk = vec3f(0.015, 0.19, 0.25); }
  let patterned = mix(wash, motifInk, clamp(marks * patternStyle.x * rest * inset, 0.0, 1.0));
  let color = loFinish(patterned, region, p, ink);
  return vec4f(color, 1.0);
}
`;

const regionValues = ['complexity', 'concavity', 'corridorWidth', 'growth', 'motion', 'nesting', 'seed', 'size'] as const;
const watercolorValues = ['blooms', 'contrast', 'palette', 'pooling', 'saturation', 'warmth'] as const;
const boundaryValues = ['accent', 'grain', 'handDrawn', 'width'] as const;
const phrasingValues = ['composition', 'hierarchy', 'pace', 'phrasing', 'tension', 'time'] as const;

function exactKeys(record: Readonly<Record<string, unknown>>, expected: readonly string[]): boolean {
  const keys = Object.keys(record).sort();
  return keys.length === expected.length && keys.every((key, index) => key === expected[index]);
}

function fieldData(resource: ShaderFieldResource, abi: string, expectedValues: readonly string[]) {
  const data = resource.data;
  if (data.version !== 1 || data.abi !== abi) {
    throw Error(`Living Ornament requires shader field ${abi}.`);
  }
  if (!exactKeys(data.fragments, ['helpers']) || !exactKeys(data.values, expectedValues)) {
    throw Error(`Living Ornament ${abi} requires exactly its helpers fragment and declared value keys.`);
  }
  return data;
}

export default defineComponent({
  metadata: {
    declarationVersion: 1,
    key: 'lux/ornament-region-styles',
    label: 'Ornament Region Styles',
    description: 'Paints fitted organic silhouettes with animated watercolor, bold boundaries, and a shared artistic clock.',
    tags: ['ornament', 'regions', 'watercolor'],
    inputs: {
      regions: {
        type: { kind: 'shader-field', version: 1, abi: 'lux/ornament-regions/v1' },
        label: 'Regions', description: 'Fitted organic region geometry, local coordinates, and visible boundary distance.',
      },
      watercolor: {
        type: { kind: 'shader-field', version: 1, abi: 'lux/ornament-watercolor/v1' },
        label: 'Watercolor', description: 'Shape-aware pigment, quiet washes, and selective dark masses.',
      },
      boundary: {
        type: { kind: 'shader-field', version: 1, abi: 'lux/ornament-boundary-ink/v1' },
        label: 'Boundary ink', description: 'Coherent organic ink around visible owning boundaries.',
      },
      phrasing: {
        type: { kind: 'shader-field', version: 1, abi: 'lux/ornament-phrasing/v1' },
        label: 'Phrasing', description: 'Shared artistic time, deterministic noise, quiet balance, and size hierarchy.',
      },
    },
    outputs: {
      image: {
        type: { kind: 'image', colorSpace: 'linear-srgb', alphaMode: 'premultiplied' },
        label: 'Image', description: 'Opaque living ornament painting.',
      },
    },
    controls: {
      patternDensity: { type: 'number', group: 'Patterns', label: 'Density', default: 1, min: 0.3, max: 2, step: 0.01 },
      patternWidth: { type: 'number', group: 'Patterns', label: 'Line width', default: 1, min: 0.3, max: 2, step: 0.01 },
      patternVariation: { type: 'number', group: 'Patterns', label: 'Variation', default: 0.7, min: 0, max: 1, step: 0.01 },
      patternStrength: { type: 'number', group: 'Patterns', label: 'Ink strength', default: 1, min: 0, max: 1, step: 0.01 },
      patternRest: { type: 'number', group: 'Patterns', label: 'Quiet areas', default: 0.9, min: 0, max: 1, step: 0.01 },
      patternMotion: { type: 'number', group: 'Pattern Motion', label: 'Flow', default: 0.2, min: 0, max: 1, step: 0.01 },
    },
    controlDescriptions: {
      patternDensity: 'Sets the scale and spacing of region motifs.',
      patternWidth: 'Sets motif stroke thickness.',
      patternVariation: 'Varies motif size and curvature within each family.',
      patternStrength: 'Blends motif ink into the watercolor.',
      patternRest: 'Keeps selected regions quiet between dense patterns.',
      patternMotion: 'Adds slow movement within attached patterns.',
    },
    lifecycle: { state: 'stateful', reset: 'seed' },
  },
  async create(context) {
    const aspect = context.settings.width / context.settings.height;
    const view = uniform(new Vector4(0, aspect, 7, 0));
    const shape = uniform(new Vector4(1, 0.7, 0.85, 0.11));
    const detail = uniform(new Vector4(0.65, 0.15, 0.25, 0.99));
    const pigment = uniform(new Vector4(0.07, 1.3, 1.05, 0.74));
    const materialSettings = uniform(new Vector4(0.94, 1, 0.44, 0));
    const ink = uniform(new Vector4(0.008, 0.55, 1.34, 1.48));
    const pattern = uniform(new Vector4(1, 1, 0.7, 0.2));
    const patternStyle = uniform(new Vector4(1, 0.9, 0, 0));
    const geometry = new PlaneGeometry(2, 2);
    // Match the existing painting plane and uv orientation. This component
    // creates an image directly; it does not resample a render-target texture.
    const camera = new OrthographicCamera(-1, 1, 1, -1, 0, 1);
    let material: MeshBasicNodeMaterial | undefined;
    let scene: Scene | undefined;
    let capturedHelpers: readonly string[] | undefined;

    return {
      update(frame) {
        pattern.value.set(frame.controls.patternDensity, frame.controls.patternWidth, frame.controls.patternVariation, frame.controls.patternMotion);
        patternStyle.value.set(frame.controls.patternStrength, frame.controls.patternRest, 0, 0);
      },
      async evaluate(inputs, evaluation) {
        const regions = fieldData(inputs.regions, 'lux/ornament-regions/v1', regionValues);
        const watercolor = fieldData(inputs.watercolor, 'lux/ornament-watercolor/v1', watercolorValues);
        const boundary = fieldData(inputs.boundary, 'lux/ornament-boundary-ink/v1', boundaryValues);
        const phrasing = fieldData(inputs.phrasing, 'lux/ornament-phrasing/v1', phrasingValues);
        const helpers = [phrasing.fragments.helpers!, regions.fragments.helpers!, watercolor.fragments.helpers!, boundary.fragments.helpers!];
        if (capturedHelpers && helpers.some((source, index) => source !== capturedHelpers![index])) {
          throw Error('Living Ornament shader field source changed; rebuild the component to apply it.');
        }
        if (!capturedHelpers) {
          capturedHelpers = Object.freeze(helpers);
          material = new MeshBasicNodeMaterial({ depthTest: false, depthWrite: false });
          material.fragmentNode = wgslFn(paintPass + '\n' + helpers.join('\n') + '\n' + ornamentPackedPatterns + '\n' + ornamentLinePatternHelpers + '\n' + ornamentRibbonPatternHelpers)(
            uv(), view, shape, detail, pigment, materialSettings, ink, pattern, patternStyle,
          );
          scene = new Scene();
          const mesh = new Mesh(geometry, material);
          mesh.frustumCulled = false;
          scene.add(mesh);
        }

        // The four producers remain the sole owners of their live controls.
        // Reuse the uniform nodes and material as their scalar snapshots change.
        view.value.set(phrasing.values.time!, aspect, regions.values.seed!, 0);
        shape.value.set(regions.values.size!, regions.values.complexity!, regions.values.concavity!, regions.values.corridorWidth!);
        detail.value.set(regions.values.nesting!, regions.values.motion!, regions.values.growth!, phrasing.values.hierarchy!);
        pigment.value.set(watercolor.values.palette!, watercolor.values.warmth!, watercolor.values.contrast!, watercolor.values.pooling!);
        materialSettings.value.set(watercolor.values.blooms!, watercolor.values.saturation!, phrasing.values.composition!, 0);
        ink.value.set(boundary.values.width!, boundary.values.accent!, boundary.values.handDrawn!, boundary.values.grain!);
        return { image: await evaluation.render(scene!, camera) };
      },
      reset() {},
      dispose() {
        geometry.dispose();
        material?.dispose();
      },
    };
  },
});
","ornament-ribbon-patterns.ts":"// Shared LoRegion, loHash and loNoise come from the ornament geometry/phrasing
// fields. settings = (density, width, variation, motion); defaults (1,1,.7,.2).
// Coverage is independent of pigment, so the consumer can draw light or dark ink.
export const ornamentRibbonPatternHelpers = `
fn loRibbonMarks(r: LoRegion, p: vec2f, t: f32, settings: vec4f) -> f32 {
  let density = max(settings.x, 0.08);
  let width = clamp(settings.y, 0.1, 3.0);
  let variety = clamp(settings.z, 0.0, 1.5);
  let identity = vec2f(r.identity * 1.731, r.parent * 0.913 + 23.7);
  let family = loHash(identity + 41.3);
  let character = loHash(identity + 83.1);
  let axis = normalize(r.tangent + vec2f(0.00001, 0.0));
  let side = vec2f(-axis.y, axis.x);
  let along = dot(r.local, axis);
  let across = dot(r.local, side);
  let sway = settings.w * 0.018 * sin(t * 0.17 + character * 6.28318);
  let bend = variety * 0.025 * sin(along * 3.4 + character * 8.0 + sway);
  let laneWidth = mix(0.13, 0.22, character) / sqrt(density);
  let transverse = (across + bend) / laneWidth;
  let spacing = mix(0.085, 0.14, loHash(identity + 107.0)) / density;
  let phase = along / spacing + character * 7.0;
  let rungId = floor(phase + 0.5);
  let jitter = (loHash(vec2f(rungId, r.identity + 11.0)) - 0.5) * 0.13 * variety;
  let rungDistance = abs(fract(phase + jitter + 0.5) - 0.5);
  let rungAA = max(fwidth(phase), 0.006);
  let transverseAA = max(fwidth(transverse), 0.006);

  // A long ladder follows the shape: two calm rails and individual crossbars.
  let band = 1.0 - smoothstep(0.84, 0.84 + transverseAA, abs(transverse));
  let railDistance = abs(abs(transverse) - 0.80);
  let rails = 1.0 - smoothstep(0.028 * width, 0.028 * width + transverseAA, railDistance);
  let rungs = (1.0 - smoothstep(0.048 * width, 0.048 * width + rungAA, rungDistance)) * band;
  let ladder = 1.0 - (1.0 - rails) * (1.0 - rungs);

  // Alternating bead sizes make a necklace rather than a uniform dotted line.
  let beadSize = 0.23 + 0.07 * loHash(vec2f(rungId + 67.0, r.identity));
  let beadPoint = vec2f((fract(phase + jitter + 0.5) - 0.5), transverse * 0.56);
  let beadDistance = length(beadPoint);
  let beadAA = max(fwidth(beadDistance), 0.008);
  let pearl = 1.0 - smoothstep(beadSize * sqrt(width), beadSize * sqrt(width) + beadAA, beadDistance);
  let beadRim = 1.0 - smoothstep(0.032 * width, 0.032 * width + beadAA, abs(beadDistance - beadSize));
  let beads = mix(pearl, beadRim, step(0.58, character));

  // The third family is a broad ribbon of closely spaced transverse bands.
  let ribbonBand = 1.0 - smoothstep(0.91, 0.91 + transverseAA, abs(transverse));
  let stripes = (1.0 - smoothstep(0.15 * width, 0.15 * width + rungAA, rungDistance)) * ribbonBand;
  let pattern = mix(mix(ladder, beads, step(0.36, family)), stripes, step(0.73, family));
  let boundaryAA = max(fwidth(r.edge), 0.0004);
  let inset = smoothstep(0.006, 0.018 + boundaryAA, r.edge);
  return clamp(pattern * inset, 0.0, 1.0);
}

fn loHatchMarks(r: LoRegion, p: vec2f, t: f32, settings: vec4f) -> f32 {
  let density = max(settings.x, 0.08);
  let width = clamp(settings.y, 0.1, 3.0);
  let variety = clamp(settings.z, 0.0, 1.5);
  let identity = vec2f(r.identity * 1.317 + 71.0, r.parent * 0.739 + 19.0);
  let angle = (loHash(identity) - 0.5) * 2.8 * variety;
  let flow = normalize(r.tangent + vec2f(0.00001, 0.0));
  let axis = vec2f(flow.x * cos(angle) - flow.y * sin(angle), flow.x * sin(angle) + flow.y * cos(angle));
  let along = dot(r.local, axis);
  let across = dot(r.local, vec2f(-axis.y, axis.x));
  let character = loHash(identity + 43.7);
  let drift = settings.w * 0.12 * sin(t * 0.15 + character * 6.28318);
  let bend = variety * (0.022 * sin(along * (3.0 + character * 2.0) + character * 9.0 + drift)
    + 0.014 * (loNoise(vec2f(along * 5.0, character * 17.0)) - 0.5));
  let spacing = mix(0.027, 0.067, loHash(identity + 103.0)) / density;
  let phase = (across + bend) / spacing;
  let lineId = floor(phase + 0.5);
  let jitter = (loHash(vec2f(lineId, r.identity + 149.0)) - 0.5) * 0.12 * variety;
  let distance = abs(fract(phase + jitter + 0.5) - 0.5);
  let aa = max(fwidth(phase), 0.006);
  let pressure = 0.83 + 0.28 * loNoise(vec2f(along * 8.0, lineId * 1.7 + character * 3.0));
  let strokeWidth = min(0.23, 0.035 * width * pressure + aa * 0.35);
  let stroke = 1.0 - smoothstep(strokeWidth, strokeWidth + aa, distance);

  let crossPhase = (along + variety * 0.012 * sin(across * 5.0 + character * 7.0 + drift)) / (spacing * 1.43);
  let crossDistance = abs(fract(crossPhase + 0.5) - 0.5);
  let crossAA = max(fwidth(crossPhase), 0.006);
